-- ----------------------------
-- Table structure for upms_china_region
-- ----------------------------
DROP TABLE IF EXISTS `upms_china_region`;
CREATE TABLE `upms_china_region`  (
  `code` varchar(31) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '区域编码',
  `parent_code` varchar(31) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父编码',
  `name` varchar(31) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区域名称',
  `level` int NULL DEFAULT NULL COMMENT '区域级别(1:省/直辖市，2:地级，3:区/县级)',
  `count_chi` int NULL DEFAULT 0 COMMENT '孩子节点数',
  `full_path` varchar(63) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '全路径',
  `full_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '全名',
  `is_delete` bit(1) NULL DEFAULT b'0' COMMENT '逻辑删除',
  `upsert_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作者',
  `upsert_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`code`) USING BTREE,
  UNIQUE INDEX `puk_code`(`code` ASC) USING BTREE,
  INDEX `idx_is_delete`(`is_delete` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '中国地理位置(仅到区县级)' ROW_FORMAT = Dynamic;

